function Cliff2(amber17) {
  let basalt17 = WorkbookR(amber17 ?? ""),
    cedar17 = [],
    daisy17 = [],
    ember17 = [],
    flint17 = [],
    garnet17 = null,
    hazel17;
  for (let ivory17 = 0; ivory17 < basalt17.length; ivory17 += 1) {
    let jasper17 = basalt17[ivory17];
    if (!jasper17 || jasper17.type === "EOF") continue;
    let kelp17 = amber17.slice(jasper17.start, jasper17.end);
    if (jasper17.type === "Whitespace") {
      cedar17.push({
        kind: "ws",
        from: jasper17.start,
        to: jasper17.end,
        text: kelp17,
      });
      continue;
    }
    if (
      jasper17.type === "Identifier" &&
      basalt17[ivory17 + 1]?.type === "Bang"
    ) {
      let olive17 = Oak2(kelp17),
        prism17 = {
          kind: "sheet_name",
          from: jasper17.start,
          to: jasper17.end,
          text: kelp17,
          norm: olive17,
        };
      cedar17.push(prism17);
      daisy17.push(Fern2(prism17.from, prism17.to));
      garnet17 = olive17;
      continue;
    }
    if (jasper17.type === "Bang") {
      let quill17 = {
        kind: "op",
        from: jasper17.start,
        to: jasper17.end,
        text: kelp17,
      };
      cedar17.push(quill17);
      daisy17.push(Fern2(quill17.from, quill17.to));
      hazel17 = garnet17 ?? undefined;
      garnet17 = null;
      continue;
    }
    let lotus17 = Grove2(basalt17, ivory17 + 1),
      mint17 =
        (jasper17.type === "Identifier" || jasper17.type === "Boolean") &&
        lotus17?.type === "ParenOpen";
    if (!mint17) {
      let reef17 = js(basalt17, ivory17, amber17, hazel17);
      if (reef17) {
        cedar17.push(reef17.token);
        daisy17.push(reef17.highlight);
        ember17.push(reef17.refSpan);
        ivory17 = reef17.nextIndex - 1;
        hazel17 = undefined;
        continue;
      }
    }
    hazel17 &&= undefined;
    let nova17 = Dusk2(jasper17, kelp17);
    mint17 && nova17.kind === "ident"
      ? ((nova17.norm = kelp17.toUpperCase()),
        daisy17.push({
          kind: "func",
          from: nova17.from,
          to: nova17.to,
        }))
      : Elm2(nova17, daisy17, flint17);
    cedar17.push(nova17);
  }
  return {
    tokens: cedar17,
    highlights: daisy17,
    refs: ember17,
    errors: flint17.length > 0 ? flint17 : undefined,
  };
}
function Dusk2(sage17, topaz17) {
  let ultra17 = {
    from: sage17.start,
    to: sage17.end,
    text: topaz17,
  };
  switch (sage17.type) {
    case "Number":
      return {
        ...ultra17,
        kind: "number",
      };
    case "String":
      return {
        ...ultra17,
        kind: "string",
      };
    case "Boolean":
    case "Identifier":
      return {
        ...ultra17,
        kind: "ident",
      };
    case "Error":
      return {
        ...ultra17,
        kind: "error",
      };
    case "Operator":
    case "ParenOpen":
    case "ParenClose":
    case "Comma":
    case "Colon":
    case "At":
    case "Hash":
    case "LBrace":
    case "RBrace":
    case "Semicolon":
      return {
        ...ultra17,
        kind: "op",
      };
    default:
      return {
        ...ultra17,
        kind: "unknown",
      };
  }
}
